roles = {
    "pod-reader": [{"resource": "pods", "verbs": ["get", "list"]}],
    "deployment-editor": [{"resource": "deployments", "verbs": ["get", "list", "update"]}],
}

role_bindings = [
    {"subject": "sa:ci-bot", "role": "pod-reader", "namespace": "shop"},
    {"subject": "sa:deploy-bot", "role": "deployment-editor", "namespace": "shop"},
]


def allowed(subject, namespace, resource, verb):
    for binding in role_bindings:
        if binding["subject"] != subject or binding["namespace"] != namespace:
            continue
        for rule in roles[binding["role"]]:
            if rule["resource"] == resource and verb in rule["verbs"]:
                return True
    return False


checks = [
    ("sa:ci-bot", "shop", "pods", "get"),
    ("sa:ci-bot", "shop", "pods", "delete"),
    ("sa:deploy-bot", "shop", "deployments", "update"),
    ("sa:ci-bot", "billing", "pods", "get"),
]

for subject, ns, resource, verb in checks:
    result = "allow" if allowed(subject, ns, resource, verb) else "deny"
    print(f"{subject} {verb} {resource} in {ns}: {result}")
